--      from blank_columns b
--      where b.x_positions between least(s.x,s.other_x) and greatest(s.x,s.other_x)
--      ) more_x2
---- why does `more_x` not equal to `more_x2`
--
--
--from star_pairs s
--where s.star# = 5 and s.other_star = 9;


select
  sum(abs(delta_x) + abs(delta_y) + (more_x*(1000000 - 1)) + (more_y*(1000000 - 1)) ) min_distance
  ,sum( ceil(sqrt( power( abs(delta_x) + more_x*10, 2) + power( abs(delta_y)+more_y, 2 ) )) ) min2
from star_pairs